const $=id=>document.getElementById(id), svg=$('map'), paths=[...svg.querySelectorAll('path')];
const fmt=n=>n.toLocaleString('en-GB'), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selected=null;const base=[-18,-18,782.78,886];let box=[...base];
function metricText(r,m){return m==='n'?fmt(r.n):m==='coverage'?(r.coverage*100).toFixed(1)+'%':r[m].toFixed(2);}
function rows(){return DATA[$('year').value]||{};}
function draw(){const rs=rows(),m=$('metric').value,suppress=$('suppress').checked;let shown=0,total=0;
for(const p of paths){const r=rs[p.dataset.code];const hidden=!r||((m==='chq'||m==='potential')&&suppress&&r.n<100);p.setAttribute('fill',hidden?'#dce2e8':fill(r[m],m));if(r){total+=r.n;if(!hidden)shown++;}}
const spec={chq:[50,90,'Scores: 0–100. Fixed colour scale: 50–90. Grey: no records or insufficient sample size.'],potential:[50,90,'Equal-weight mean of 49 variables including potential performance. Fixed colour scale: 50–90.'],n:[100,100000,'Transaction counts on a logarithmic colour scale. Values below 100 use the lower endpoint colour.'],coverage:[.78,.93,'Mean available variables / 41. Colour scale: 78%–93%; values outside this range use endpoint colours.']};
const [lo,hi,note]=spec[m];$('legendLo').textContent=m==='coverage'?'78%':fmt(lo);$('legendHi').textContent=m==='coverage'?'93%':fmt(hi);$('legendNote').textContent=note;
$('gradient').style.background='linear-gradient(to right,'+PALETTES[m].filter((x,i)=>i%17===0||i===255).join(',')+')';
$('status').textContent=fmt(total)+' transactions · '+shown+' areas coloured';
$('rankingTitle').textContent={chq:'Authorities with higher CHQ',potential:'Authorities with higher CHQ + potential',n:'Authorities with more transactions',coverage:'Authorities with higher completeness'}[m];
let ranked=Object.entries(rs).filter(([c,r])=>r.n>=100).sort((a,b)=>b[1][m]-a[1][m]).slice(0,5);$('ranking').innerHTML=ranked.map(([c,r])=>'<button class="rank-row" type="button" data-select="'+c+'"><span>'+esc(r.name)+'</span><strong>'+metricText(r,m)+'</strong></button>').join('');
$('ranking').querySelectorAll('button').forEach(b=>b.onclick=()=>choose(b.dataset.select));
if(selected&&!rs[selected]){$('searchMessage').textContent='No records for the selected area in this year. Showing all areas.';selected=null;}details(selected);}
function fill(value,m){let t=m==='n'?(Math.log10(Math.max(1,value))-2)/3:m==='coverage'?(value-.78)/.15:(value-50)/40;return PALETTES[m][Math.round(Math.max(0,Math.min(1,t))*255)];}
function details(code){let r=code?rows()[code]:null,m=$('metric').value;
if(!r){const rr=Object.values(rows()),n=rr.reduce((a,r)=>a+r.n,0),avg=key=>rr.reduce((a,r)=>a+r.n*r[key],0)/n;r={name:'England & Wales',region:'Selected period · All mapped transactions',n,chq:avg('chq'),potential:avg('potential'),coverage:avg('coverage'),variables:avg('variables')};}
$('name').textContent=r.name;$('region').textContent=r.region;$('code').textContent=code||'—';$('count').textContent=fmt(r.n);$('coverage').textContent=(r.coverage*100).toFixed(1)+'%';$('variables').textContent=r.variables.toFixed(1)+'/41';
$('score').textContent=m==='n'?fmt(r.n):m==='coverage'?(r.coverage*100).toFixed(1)+'%':r[m].toFixed(2);$('scoreLabel').textContent=$('metric').selectedOptions[0].text;
$('selectionNote').textContent=r.n<100?'This area has only '+r.n+' transactions. The mean may be unstable; interpret it alongside the sample size.':'Sales-sample mean, unadjusted for year, dwelling mix or missing-variable mix. It does not establish causation.';
for(const p of paths)p.classList.toggle('active',p.dataset.code===code);}
for(const p of paths){p.addEventListener('pointermove',e=>{const r=rows()[p.dataset.code];if(!r)return;if(!selected)details(p.dataset.code);const tip=$('tooltip');tip.innerHTML='<strong>'+esc(r.name)+'</strong><br>'+esc($('metric').selectedOptions[0].text)+' '+metricText(r,$('metric').value)+' · n = '+fmt(r.n);tip.style.display='block';tip.style.left=Math.min(e.clientX+15,window.innerWidth-300)+'px';tip.style.top=Math.min(e.clientY+15,window.innerHeight-80)+'px';});p.addEventListener('pointerleave',()=>{$('tooltip').style.display='none';if(!selected)details(null);});p.setAttribute('tabindex','0');p.setAttribute('role','button');p.setAttribute('aria-label',DATA.all[p.dataset.code].name);p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(p.dataset.code);}});p.addEventListener('click',()=>{if(moved)return;choose(selected===p.dataset.code?null:p.dataset.code);});}
function setBox(){svg.setAttribute('viewBox',box.join(' '));}function zoom(f,cx=box[0]+box[2]/2,cy=box[1]+box[3]/2){const w=box[2]*f;if(w<base[2]/16||w>base[2]*1.6)return;box=[cx+(box[0]-cx)*f,cy+(box[1]-cy)*f,w,box[3]*f];setBox();}
svg.addEventListener('wheel',e=>{e.preventDefault();const q=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());zoom(e.deltaY<0?.85:1.18,q.x,q.y);},{passive:false});
let drag=null,moved=false;svg.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY,...box];moved=false;});window.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag[0],dy=e.clientY-drag[1];if(Math.abs(dx)+Math.abs(dy)>4)moved=true;const units=1/svg.getScreenCTM().a;box=[drag[2]-dx*units,drag[3]-dy*units,drag[4],drag[5]];setBox();});window.addEventListener('pointerup',()=>{drag=null;setTimeout(()=>moved=false,0);});
$('plus').onclick=()=>zoom(.75);$('minus').onclick=()=>zoom(1.33);$('reset').onclick=()=>{box=[...base];selected=null;setBox();details(null);};for(const id of ['metric','year','suppress'])$(id).onchange=draw;
function choose(code){selected=code;if(code&&!rows()[code]){selected=null;$('searchMessage').textContent='No records for this authority in the selected year.';}else{$('searchMessage').textContent='';}details(selected);}
$('areaOptions').innerHTML=Object.entries(DATA.all).sort((a,b)=>a[1].name.localeCompare(b[1].name)).map(([c,r])=>'<option value="'+esc(r.name)+'">'+c+'</option>').join('');
$('searchForm').onsubmit=e=>{e.preventDefault();const query=$('areaSearch').value.trim().toLowerCase();if(!query){choose(null);return;}const match=Object.entries(DATA.all).find(([c,r])=>r.name.toLowerCase()===query||c.toLowerCase()===query);if(match){choose(match[0]);}else{$('searchMessage').textContent='Authority not found. Choose a suggested name or enter a complete code.';}};
$('reset').onclick=()=>{box=[...base];setBox();$('areaSearch').value='';choose(null);};draw();
